from typing import Dict, Any, Optional
from .schemas import FullTaskContext, ActionType

class PlatformToolkit:
    """
    Encapsulates all platform-specific API calls and database mutations.
    Allows safe sandboxing of external integrations.
    """

    def __init__(self, db_session: Optional[Any] = None, api_client: Optional[Any] = None):
        """
        Initialize toolkit with optional dependency injections.

        Args:
            db_session: SQLAlchemy session or your ORM instance
            api_client: HTTP client for external PM tool APIs (Jira, Linear, etc.)
        """
        self.db = db_session
        self.api = api_client

    def move_task_column(
        self,
        task_id: str,
        board_id: str,
        target_column: str
    ) -> bool:
        """Move task to a different workflow column."""
        try:
            # Example: SQLAlchemy update
            if self.db:
                # from app.models import Task
                # self.db.query(Task).filter(Task.id == task_id).update({"column": target_column})
                # self.db.commit()
                pass

            print(f"✓ Moved task {task_id} to column: {target_column}")
            return True
        except Exception as e:
            print(f"✗ Failed to move task: {e}")
            return False

    def update_checklist(
        self,
        task_id: str,
        checklist_updates: Dict[str, bool]
    ) -> bool:
        """
        Update checklist item completion statuses.

        Args:
            task_id: Task identifier
            checklist_updates: Dict of {checklist_item_id: completed_bool}
        """
        try:
            print(f"✓ Updated checklist for task {task_id}: {checklist_updates}")
            return True
        except Exception as e:
            print(f"✗ Failed to update checklist: {e}")
            return False

    def add_task_label(
        self,
        task_id: str,
        labels: list
    ) -> bool:
        """Add or update task labels."""
        try:
            print(f"✓ Added labels to task {task_id}: {labels}")
            return True
        except Exception as e:
            print(f"✗ Failed to add labels: {e}")
            return False

    def post_chat_message(
        self,
        task_id: str,
        message: str,
        sender_name: str = "AI Project Manager"
    ) -> bool:
        """Post a message in task's chat/timeline."""
        try:
            print(f"✓ Posted message on task {task_id}: [{sender_name}] {message}")
            return True
        except Exception as e:
            print(f"✗ Failed to post message: {e}")
            return False

    def execute_agent_decision(
        self,
        task_id: str,
        action_type: str,
        action_payload: Dict[str, Any]
    ) -> bool:
        """
        Route agent decision to appropriate tool based on action_type.
        """
        action_type_enum = ActionType(action_type)

        if action_type_enum == ActionType.MOVE_COLUMN:
            return self.move_task_column(
                task_id=task_id,
                board_id=action_payload.get("board_id"),
                target_column=action_payload.get("target_column")
            )

        elif action_type_enum == ActionType.UPDATE_CHECKLIST:
            return self.update_checklist(
                task_id=task_id,
                checklist_updates=action_payload.get("items", {})
            )

        elif action_type_enum == ActionType.ADD_LABEL:
            return self.add_task_label(
                task_id=task_id,
                labels=action_payload.get("labels", [])
            )

        elif action_type_enum == ActionType.POST_CHAT_MESSAGE:
            return self.post_chat_message(
                task_id=task_id,
                message=action_payload.get("message", ""),
                sender_name=action_payload.get("sender_name", "AI PM")
            )

        elif action_type_enum == ActionType.NONE:
            print(f"💤 No action required for task {task_id}")
            return True

        else:
            print(f"✗ Unknown action type: {action_type}")
            return False

"""Custom exceptions for PM Agent module."""

class PMAgentException(Exception):
    """Base exception for PM Agent errors."""
    pass

class PMAgentInitializationError(PMAgentException):
    """Raised when PM Agent initialization fails."""
    pass

class PMAgentProcessingError(PMAgentException):
    """Raised when task event processing fails."""
    pass

class MemoryDeserializationError(PMAgentException):
    """Raised when memory snapshot deserialization fails."""
    pass

class PlatformToolError(PMAgentException):
    """Raised when platform tool execution fails."""
    pass

from typing import Dict, Any, Optional, Callable
from .schemas import FullTaskContext, ActionType
from .exceptions import PlatformToolError

class PlatformToolkit:
    """
    Encapsulates all platform-specific API calls and database mutations.
    Accepts dependency-injected callbacks for seamless codx-junior integration.

    Design: Tools are abstracted as callable functions to support
    multiple platform implementations.
    """

    def __init__(
        self,
        move_column_fn: Optional[Callable] = None,
        update_checklist_fn: Optional[Callable] = None,
        add_label_fn: Optional[Callable] = None,
        post_message_fn: Optional[Callable] = None,
        db_session: Optional[Any] = None,
        api_client: Optional[Any] = None
    ):
        """
        Initialize toolkit with dependency-injected tool functions.

        Args:
            move_column_fn: Callback for moving task columns
            update_checklist_fn: Callback for updating checklist items
            add_label_fn: Callback for adding labels
            post_message_fn: Callback for posting chat messages
            db_session: Optional database session (SQLAlchemy, etc.)
            api_client: Optional HTTP client for external integrations
        """
        self.move_column_fn = move_column_fn
        self.update_checklist_fn = update_checklist_fn
        self.add_label_fn = add_label_fn
        self.post_message_fn = post_message_fn
        self.db = db_session
        self.api = api_client

    def move_task_column(
        self,
        task_id: str,
        board_id: str,
        target_column: str
    ) -> bool:
        """Move task to a different workflow column."""
        try:
            if self.move_column_fn:
                return self.move_column_fn(
                    task_id=task_id,
                    board_id=board_id,
                    target_column=target_column
                )
            else:
                # Fallback if no callback provided
                print(f"✓ [Mock] Moved task {task_id} to column: {target_column}")
                return True
        except Exception as e:
            raise PlatformToolError(f"Failed to move task: {str(e)}")

    def update_checklist(
        self,
        task_id: str,
        checklist_updates: Dict[str, bool]
    ) -> bool:
        """
        Update checklist item completion statuses.

        Args:
            task_id: Task identifier
            checklist_updates: Dict of {checklist_item_id: completed_bool}
        """
        try:
            if self.update_checklist_fn:
                return self.update_checklist_fn(
                    task_id=task_id,
                    checklist_updates=checklist_updates
                )
            else:
                print(f"✓ [Mock] Updated checklist for task {task_id}: {checklist_updates}")
                return True
        except Exception as e:
            raise PlatformToolError(f"Failed to update checklist: {str(e)}")

    def add_task_label(
        self,
        task_id: str,
        labels: list
    ) -> bool:
        """Add or update task labels."""
        try:
            if self.add_label_fn:
                return self.add_label_fn(
                    task_id=task_id,
                    labels=labels
                )
            else:
                print(f"✓ [Mock] Added labels to task {task_id}: {labels}")
                return True
        except Exception as e:
            raise PlatformToolError(f"Failed to add labels: {str(e)}")

    def post_chat_message(
        self,
        task_id: str,
        message: str,
        sender_name: str = "AI Project Manager"
    ) -> bool:
        """Post a message in task's chat/timeline."""
        try:
            if self.post_message_fn:
                return self.post_message_fn(
                    task_id=task_id,
                    message=message,
                    sender_name=sender_name
                )
            else:
                print(f"✓ [Mock] Posted message on task {task_id}: [{sender_name}] {message}")
                return True
        except Exception as e:
            raise PlatformToolError(f"Failed to post message: {str(e)}")

    def execute_agent_decision(
        self,
        task_id: str,
        action_type: str,
        action_payload: Dict[str, Any]
    ) -> bool:
        """
        Route agent decision to appropriate tool based on action_type.
        """
        try:
            action_type_enum = ActionType(action_type)

            if action_type_enum == ActionType.MOVE_COLUMN:
                return self.move_task_column(
                    task_id=task_id,
                    board_id=action_payload.get("board_id"),
                    target_column=action_payload.get("target_column")
                )

            elif action_type_enum == ActionType.UPDATE_CHECKLIST:
                return self.update_checklist(
                    task_id=task_id,
                    checklist_updates=action_payload.get("items", {})
                )

            elif action_type_enum == ActionType.ADD_LABEL:
                return self.add_task_label(
                    task_id=task_id,
                    labels=action_payload.get("labels", [])
                )

            elif action_type_enum == ActionType.POST_CHAT_MESSAGE:
                return self.post_chat_message(
                    task_id=task_id,
                    message=action_payload.get("message", ""),
                    sender_name=action_payload.get("sender_name", "AI PM")
                )

            elif action_type_enum == ActionType.NONE:
                print(f"💤 No action required for task {task_id}")
                return True

            else:
                raise ValueError(f"Unknown action type: {action_type}")

        except Exception as e:
            raise PlatformToolError(f"Decision execution failed: {str(e)}")
